                    @endif

                    {{-- Custom 5-Page Window --}}
                    @php
                        $start = $paginator->currentPage() - 2;
                        $end = $paginator->currentPage() + 2;

                        if ($start < 1) {
                            $end += 1 - $start;
                            $start = 1;
                        }
                        if ($end > $paginator->lastPage()) {
                            $start -= $end - $paginator->lastPage();
                            $end = $paginator->lastPage();
                        }
                        if ($start < 1) $start = 1;
                    @endphp

                    @if ($start > 1)
                        <span aria-disabled="true">
                                <span class="inline-flex items-center px-4 py-2 -ml-px text-sm font-medium text-gray-500 bg-white border border-gray-300 cursor-default leading-5 dark:bg-gray-800 dark:border-gray-600 dark:text-gray-400">...</span>
                            </span>
                    @endif

                    @for ($page = $start; $page <= $end; $page++)
                        @if ($page == $paginator->currentPage())
                            <span aria-current="page">
                                <span class="inline-flex items-center px-4 py-2 -ml-px text-sm font-bold text-white bg-teal-600 border border-teal-600 cursor-default leading-5 dark:bg-teal-500 dark:border-teal-500">{{ $page }}</span>
                            </span>
                        @else
                            <a href="{{ $paginator->url($page) }}" class="inline-flex items-center px-4 py-2 -ml-px text-sm font-medium text-gray-700 bg-white border border-gray-300 leading-5 hover:text-gray-700 hover:bg-gray-50 focus:outline-none focus:ring ring-teal-300 focus:border-teal-300 transition ease-in-out duration-150 dark:bg-gray-800 dark:border-gray-600 dark:text-gray-300 dark:hover:bg-gray-700" aria-label="{{ __('Go to page :page', ['page' => $page]) }}">
                                {{ $page }}
                            </a>
                        @endif
                    @endfor

